(()=>{const g=new OffscreenCanvas(2,2).getContext('webgl'),e=g.getExtension('WEBGL_debug_shaders'),s=g.createShader(g.VERTEX_SHADER),out={tag:Object.prototype.toString.call(e),fresh:e.getTranslatedShaderSource(s),error:g.getError()};g.shaderSource(s,'void main(){gl_Position=vec4(0.);}');out.sourceOnly=e.getTranslatedShaderSource(s);g.compileShader(s);out.compiledNonempty=e.getTranslatedShaderSource(s).length>0;g.shaderSource(s,'void main(){gl_Position=vec4(1.);}');out.stillCompiled=e.getTranslatedShaderSource(s).length>0;g.deleteShader(s);out.deleted=e.getTranslatedShaderSource(s);out.deletedError=g.getError();for(const v of [null,{},g.createProgram()]){try{out[String(v)]=[e.getTranslatedShaderSource(v),g.getError()]}catch(err){out[String(v)]=[err.name]}}return out})()
